{
  "report": "Visão geral (até 2024-07-01): EQTL3 mostra uma reversão de curto/médio prazo. Fechamento em 32,03 no pregão de 01/07/2024 vem acima das médias de curto prazo (MM20=29,636; MM50=30,275) e das EMAs (EMA9=30,256; EMA21=29,940), sinalizando recuperação imediata. Entretanto o preço ainda está ligeiramente abaixo da MM200 (32,675), o que preserva um viés baixista em horizonte de longo prazo. O conjunto de indicadores aponta para um sinal de alta de curto/médio prazo com convicção moderada, mas com risco de pullback após movimento abrupto.",
  "signal": "Alta",
  "support_levels": [
    30.2754,
    29.636,
    28.7
  ],
  "resistance_levels": [
    32.6754,
    33.2428,
    34.2069
  ],
  "indicator_readings": [
    {
      "indicator": "Fechamento",
      "reading": "32.03",
      "interpretation": "Fechamento acima de MM20/MM50 e EMAs, confirma perna de alta de curto prazo."
    },
    {
      "indicator": "MM20",
      "reading": "29.6360",
      "interpretation": "Média curta em ascensão; atua como suporte dinâmico imediato."
    },
    {
      "indicator": "MM50",
      "reading": "30.2754",
      "interpretation": "Média de médio prazo também abaixo do preço — valida recuperação curta/média."
    },
    {
      "indicator": "MM200",
      "reading": "32.6754",
      "interpretation": "Preço ainda abaixo da MM200: tendência de longo prazo permanece neutra/baixa até quebra acima."
    },
    {
      "indicator": "EMA9",
      "reading": "30.2565",
      "interpretation": "EMA9 abaixo do preço e cruzando EMA21 — sinal de reversão de curto prazo."
    },
    {
      "indicator": "EMA21",
      "reading": "29.9401",
      "interpretation": "EMA21 confirma suporte de curto prazo; alinhamento de EMAs curto favorável."
    },
    {
      "indicator": "MACD",
      "reading": "0.1133",
      "interpretation": "MACD positivo e acima da linha de sinal (-0.2145); momentum virou positivo recentemente."
    },
    {
      "indicator": "MACD_signal",
      "reading": "-0.2145",
      "interpretation": "Linha de sinal abaixo do MACD — confirma cruzamento altista recente."
    },
    {
      "indicator": "MACD_hist",
      "reading": "0.3278",
      "interpretation": "Histograma positivo e em expansão — aumento de força compradora no curto prazo."
    },
    {
      "indicator": "Bollinger_lower",
      "reading": "28.0458",
      "interpretation": "Banda inferior bem abaixo do preço; distância amplia assimetria do movimento."
    },
    {
      "indicator": "Bollinger_mid",
      "reading": "29.6360",
      "interpretation": "MM20 = banda média; preço já acima, indicando rompimento da média de volatilidade recente."
    },
    {
      "indicator": "Bollinger_upper",
      "reading": "31.2262",
      "interpretation": "Fechamento acima da banda superior — breakout com volatilidade alta; cuidado com retração de realização."
    },
    {
      "indicator": "RSI14",
      "reading": "66.4041",
      "interpretation": "RSI em 66 — forte momento, próximo de sobrecompra (70) mas ainda não extremo."
    },
    {
      "indicator": "Volume",
      "reading": "66,513,458,400",
      "interpretation": "Volume elevado no rompimento (pico também em 27/06 = 84,728,903,500) — confirma interesse e maior convicção no movimento de alta."
    }
  ]
}
